import scala.ref.WeakReference

class Registry {
  private var listeners: List[WeakReference[Listener]] = Nil

  def add(listener: Listener): Unit = listeners ::= WeakReference(listener)

  def notifyAll(event: Event): Unit =
    listeners = listeners.flatMap(_.get)          // None drops dead entries
      .map { listener => listener.onEvent(event); WeakReference(listener) }
}
